FF, BB, TT = 0, 1, 2
desig = lambda a: a >= BB
neg = lambda a: BB if a == BB else (TT if a == FF else FF)
conj = min
disj = max

def ev(val, f):
    k = f[0]
    if k == 'a': return val[f[1]]
    if k == 'n': return neg(ev(val, f[1]))
    if k == 'c': return conj(ev(val, f[1]), ev(val, f[2]))
    if k == 'd': return disj(ev(val, f[1]), ev(val, f[2]))

def entails(gamma, a, atoms=(0, 1, 2)):
    for assign in product((FF, BB, TT), repeat=len(atoms)):
        val = dict(zip(atoms, assign))
        if all(desig(ev(val, b)) for b in gamma) and not desig(ev(val, a)):
            return False
    return True

