from itertools import product
FF, BB, TT = 0, 1, 2
desig = lambda a: a >= BB
neg = lambda a: BB if a == BB else (TT if a == FF else FF)

def ev(val, f):
    k = f[0]
    if k == 'a': return val[f[1]]
    if k == 'n': return neg(ev(val, f[1]))
    if k == 'c': return min(ev(val, f[1]), ev(val, f[2]))
    if k == 'd': return max(ev(val, f[1]), ev(val, f[2]))

def lp_valid(f, atoms=(0, 1)):
    return all(desig(ev(dict(zip(atoms, a)), f))
               for a in product((FF, BB, TT), repeat=len(atoms)))

def classically_valid(f, atoms=(0, 1)):
    return all(desig(ev(dict(zip(atoms, a)), f))
               for a in product((FF, TT), repeat=len(atoms)))

def gen(depth):
    level = [('a', 0), ('a', 1)]
    seen = set(map(str, level)); out = list(level)
    for _ in range(depth):
        nxt = []
        for f in level:
            for g in [('n', f)] + [('c', f, h) for h in level] + \
                     [('d', f, h) for h in level]:
                if str(g) not in seen:
                    seen.add(str(g)); nxt.append(g)
        out += nxt; level = nxt
    return out

if __name__ == '__main__':
    forms = gen(2)
    agree = sum(1 for f in forms if lp_valid(f) == classically_valid(f))
    print(f'{agree}/{len(forms)} formulas: LP-valid == classically valid')
    print('mismatches:', len(forms) - agree)
    v = {0: BB, 1: FF}
    vplus = {n: (TT if x in (BB, TT) else FF) for n, x in v.items()}
    print('collapse v ->', vplus)

