function ENTAILS_MIN(Gamma, A):
    atoms  <- occurring atoms of (Gamma U {A})
    models <- [ rho | for all B in Gamma: DESIG(EVAL(rho, B)) ]
    minimal <- [ rho in models |
                  no sigma in models with GLUTSET(sigma) STRICT-SUBSET GLUTSET(rho) ]
    for rho in minimal:
        if not DESIG(EVAL(rho, A)):
            return (False, rho)
    return (True, none)

function COLLAPSE_PLUS(rho):
    return  lambda n. (tt if rho(n) in {bb, tt} else ff)

# Collapsing Lemma (proved by structural induction on A):
#   EVAL(COLLAPSE_PLUS(rho), A) = tt  =>  DESIG(EVAL(rho, A))
#   EVAL(COLLAPSE_PLUS(rho), A) = ff  =>  EVAL(rho, A) = ff

function CLASSICAL_VALID_IMPLIES_LP_VALID(A):
    assume A classically valid
    for every valuation rho:
        v+ <- COLLAPSE_PLUS(rho)              # v+ is classical
        EVAL(v+, A) = tt                      # A classically valid
        DESIG(EVAL(rho, A))                   # Collapsing Lemma
    conclude  LP-valid A
